from typing import List

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    if not coeffs:
        return "0"

    # Validate that the length of coeffs matches n + 1
    if len(coeffs) != n + 1:
        raise ValueError(f"Length of coeffs ({len(coeffs)}) does not match n + 1 ({n + 1})")

    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine the sign
        if not terms:
            # First term
            if coeff < 0:
                sign = "-"
            else:
                sign = ""
        else:
            # Subsequent terms
            if coeff < 0:
                sign = "-"
            else:
                sign = "+"

        # Determine the coefficient part
        abs_coeff = abs(coeff)
        if degree == 0:
            # Constant term
            coeff_part = str(abs_coeff)
        else:
            # Non-constant term
            if abs_coeff == 1:
                coeff_part = ""
            else:
                coeff_part = str(abs_coeff)

        # Determine the variable part
        if degree == 0:
            var_part = ""
        elif degree == 1:
            var_part = "x"
        else:
            var_part = f"x^{degree}"

        term = sign + coeff_part + var_part
        terms.append(term)

    if not terms:
        return "0"

    return "".join(terms)
