def decode(encoded: str, original: str, message: str) -> str:
    # Check if lengths match
    if len(encoded) != len(original):
        return "Failed"

    # Build mapping from encoded to original
    mapping = {}
    # Also track which original letters are used to ensure bijection
    used_original = set()

    for enc, orig in zip(encoded, original):
        if enc in mapping:
            # If already mapped, check consistency
            if mapping[enc] != orig:
                return "Failed"
        else:
            # Check if this original letter is already used by another encoded letter
            if orig in used_original:
                return "Failed"
            mapping[enc] = orig
            used_original.add(orig)

    # Check if all letters in the alphabet are represented in the mapping
    # The problem says "not all letters are represented in the mapping"
    # We need to check if the mapping covers all 26 letters? Or all letters that appear?
    # Looking at the example: "AA" -> "AB" fails because A maps to both A and B (contradiction)
    # The second example works.
    # Let's check: the mapping should be a bijection on the 26 letters? 
    # Actually, the problem says "not all letters are represented in the mapping"
    # This likely means that the mapping must cover all 26 letters of the alphabet.
    # Let's check the length of the mapping. If it's less than 26, return "Failed".
    if len(mapping) < 26:
        return "Failed"

    # Now decode the message
    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            # If a character in the message is not in the mapping, we can't decode it
            return "Failed"

    return ''.join(decoded)
